import{_ as s,c as e,o as i,b0 as n}from"./chunks/framework.BWMBvyU7.js";const b=JSON.parse('{"title":"LV087-gdb-编辑和搜索源码","description":null,"frontmatter":{"title":"LV087-gdb-编辑和搜索源码","date":"2026-05-05T09:46:33.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/debug/126d443589e928c24e7191ca","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-05-05T09:46:33.652Z","fulluuid":"24e7191ca36f44f786097091d3ec8409","useduuid":"24e7191ca"}},"headers":[],"relativePath":"sdoc/Language/c/debug/126d443589e928c24e7191ca.md","filePath":"sdoc/01-编程语言/01-C语言/21-调试/LV087-gdb-编辑和搜索源码.md","lastUpdated":1777987950000}'),t={name:"sdoc/Language/c/debug/126d443589e928c24e7191ca.md"};function l(d,a,p,r,h,c){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="lv087-gdb-编辑和搜索源码" tabindex="-1">LV087-gdb-编辑和搜索源码 <a class="header-anchor" href="#lv087-gdb-编辑和搜索源码" aria-label="Permalink to &quot;LV087-gdb-编辑和搜索源码&quot;">​</a></h1><p>本节主要讲解在 GDB 内对源文件中的代码进行修改和查找，分别对应 GDB 中的 <code>edit</code> 命令和 <code>search</code> 命令。</p><h2 id="一、-gdb-edit-命令" tabindex="-1">一、 GDB edit 命令 <a class="header-anchor" href="#一、-gdb-edit-命令" aria-label="Permalink to &quot;一、 GDB edit 命令&quot;">​</a></h2><p>在 GDB 中编辑源文件使用 <code>edit</code> 命令，该命令可以在调试过程中快速定位并修改源代码。</p><h3 id="_1-语法格式" tabindex="-1">1. 语法格式 <a class="header-anchor" href="#_1-语法格式" aria-label="Permalink to &quot;1. 语法格式&quot;">​</a></h3><p><code>edit</code> 命令的语法格式如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) edit [location]</span></span>
<span class="line"><span>(gdb) edit [filename]:[location]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>其中 <code>location</code> 表示程序中的位置，该命令表示激活文件的指定位置，然后进行编辑。</p><h3 id="_2-使用示例" tabindex="-1">2. 使用示例 <a class="header-anchor" href="#_2-使用示例" aria-label="Permalink to &quot;2. 使用示例&quot;">​</a></h3><p>以下是 <code>edit</code> 命令的常见使用方式：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">edit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 表示激活文件中的第16 行的代码（光标定位到第 16 行代码的开头位置）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> func</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 表示激活文件中的 func 处的代码（光标定位到 func 函数所在行的开头位置）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 表示激活 test.c 文件的第16 行。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_3-编辑器配置" tabindex="-1">3. 编辑器配置 <a class="header-anchor" href="#_3-编辑器配置" aria-label="Permalink to &quot;3. 编辑器配置&quot;">​</a></h3><p>GDB <code>edit</code> 命令编辑文件默认使用的是 <code>ex</code> 编辑器，使用时可能会遇到以下情况：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) edit</span></span>
<span class="line"><span>bash: /bin/ex: 没有那个文件或目录</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>遇到这种问题时，可以指定任意的编辑器（例如 Vim）去编辑文件。进入 GDB 调试器前，执行如下命令设置 <code>EDITOR</code> 环境变量：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EDITOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/usr/bin/vim</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>由此，当在 GDB 调试器中执行 <code>edit</code> 命令时，就会自动进入 Vim 编辑器，从而对当前调试的程序进行修改。</p><h4 id="_3-1-临时配置" tabindex="-1">3.1 临时配置 <a class="header-anchor" href="#_3-1-临时配置" aria-label="Permalink to &quot;3.1 临时配置&quot;">​</a></h4><p>上述修改编辑器的方法只是临时生效，当退出 shell 终端后配置就会被还原，下次使用时还要再次使用这条命令。</p><h4 id="_3-2-永久配置" tabindex="-1">3.2 永久配置 <a class="header-anchor" href="#_3-2-永久配置" aria-label="Permalink to &quot;3.2 永久配置&quot;">​</a></h4><p>想要永久实现配置，需要修改配置文件。具体做法是：修改当前 home 目录下的 <code>~/.bashrc</code> 文件，在文件的最后添加上述的命令就可以实现文件的永久配置。</p><blockquote><p>Tips：修改的是当前用户的配置文件，一般不建议修改系统的配置文件，出现问题不容易恢复。配置完成重启 shell 终端，就可以完成配置。</p></blockquote><h2 id="二、-gdb-search-命令" tabindex="-1">二、 GDB search 命令 <a class="header-anchor" href="#二、-gdb-search-命令" aria-label="Permalink to &quot;二、 GDB search 命令&quot;">​</a></h2><p>在调试文件时，某些时候可能需要去寻找某一行或某一部分的代码。可以使用 <code>list</code> 显示全部的源码，然后进行查看。当源文件的代码量较少时，可以使用这种方式搜索。如果源文件的代码量很大，使用这种方式寻找效率会很低。所以 GDB 中提供了相关的源代码搜索的 <code>search</code> 命令。</p><h3 id="_1-基本语法" tabindex="-1">1. 基本语法 <a class="header-anchor" href="#_1-基本语法" aria-label="Permalink to &quot;1. 基本语法&quot;">​</a></h3><p><code>search</code> 命令的语法格式为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) search &lt;regexp&gt;</span></span>
<span class="line"><span>(gdb) reverse-search &lt;regexp&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><code>search</code>：从当前行的开始向前搜索</li><li><code>reverse-search</code>：从当前行开始向后搜索</li></ul><p>其中 <code>regexp</code> 是正则表达式，正则表达式描述了一种字符串匹配的模式，可以用来检查一个串中是否含有某种子串、将匹配的子串替换或者从某个串中取出符合某个条件的子串。很多编程语言都支持使用正则表达式。</p><h3 id="_2-常见问题" tabindex="-1">2. 常见问题 <a class="header-anchor" href="#_2-常见问题" aria-label="Permalink to &quot;2. 常见问题&quot;">​</a></h3><p>使用命令时可能会遇到以下情况：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) search func</span></span>
<span class="line"><span>Expression not found</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这表示搜索的范围没有出现要寻找的字符串，或者已经定位到了代码行的末尾。</p>`,33)])])}const u=s(t,[["render",l]]);export{b as __pageData,u as default};
